    if (
      queryProvider &&
      payment.method === 'ZALOPAY' &&
      payment.status !== 'PAID'
    ) {
      try {
        if (payment.providerConfirmedAt && payment.providerTransactionId) {
          await this.recordConfirmation(
            payment.id,
            payment.providerTransactionId,
          );
        } else if (
          payment.status === 'PENDING' &&
          payment.createRequestedAt &&
          payment.merchantOrderId
        ) {
          // Persistent query lease coalesces POS polls across API processes.
          const lease = await this.prisma.payment.updateMany({
            where: {
              id: payment.id,
              status: 'PENDING',
              providerConfirmedAt: null,
              OR: [
                { lastQueriedAt: null },
                { lastQueriedAt: { lt: new Date(Date.now() - 60_000) } },
              ],
            },
            data: { lastQueriedAt: new Date() },
          });
          if (lease.count === 1) {
            const result = await this.provider.queryOrder(
              payment.merchantOrderId,
            );
            if (
              result.state === 'PAID' &&
              result.amountVnd === payment.amountVnd &&
              result.providerTransactionId
            ) {
              await this.recordConfirmation(
                payment.id,
                result.providerTransactionId,
              );
            } else if (result.state === 'EXPIRED') {
