## 4. Đặc tả kỹ thuật triển khai cho Codex

### 4.1 Cập nhật `apps/web/src/App.tsx`

#### Bước 1: Thay thế mảng `navigation` cũ bằng cấu trúc `navGroups`
Xóa hoặc thay thế cấu hình phẳng cũ (khoảng dòng 57–71):

```tsx
interface NavGroup {
  id: string
  label: string
  icon: IconName
  items: { page: Page; icon: IconName }[]
}

const navGroups: NavGroup[] = [
  {
    id: 'stores',
    label: 'Điều hành chuỗi',
    icon: 'store',
    items: [
      { page: 'stores', icon: 'store' },
    ],
  },
  {
    id: 'menu',
    label: 'Thực đơn & Bán lẻ',
    icon: 'coffee',
    items: [
      { page: 'menu-products', icon: 'coffee' },
      { page: 'menu-categories', icon: 'menu' },
      { page: 'menu-toppings', icon: 'plus' },
    ],
  },
  {
    id: 'inventory',
    label: 'Kho & Công thức',
    icon: 'box',
    items: [
      { page: 'inventory-balances', icon: 'box' },
      { page: 'inventory-ingredients', icon: 'bars' },
      { page: 'inventory-recipes', icon: 'receipt' },
      { page: 'inventory-receipts', icon: 'box' },
    ],
  },
  {
    id: 'hr',
    label: 'Nhân sự & Chấm công',
    icon: 'users',
    items: [
      { page: 'hr-employees', icon: 'users' },
      { page: 'hr-attendance', icon: 'clock' },
    ],
  },
  {
    id: 'finance',
    label: 'Tài chính & Báo cáo',
    icon: 'wallet',
    items: [
      { page: 'sales', icon: 'receipt' },
      { page: 'register', icon: 'wallet' },
    ],
  },
]

const getGroupIdForPage = (targetPage: Page): string | null => {
  const found = navGroups.find(group => group.items.some(item => item.page === targetPage))
  return found ? found.id : null
}
```

#### Bước 2: Bổ sung State quản lý nhóm mở trong component `App`
Trong hàm `App()` (quanh dòng 2360):

```tsx
const [expandedGroupId, setExpandedGroupId] = useState<string | null>(() => getGroupIdForPage(getPage()))

useEffect(() => {
  const activeGroupId = getGroupIdForPage(page)
  if (activeGroupId) {
    setExpandedGroupId(activeGroupId)
  }
}, [page])

const toggleGroup = (groupId: string) => {
  setExpandedGroupId(prev => (prev === groupId ? null : groupId))
}
```

#### Bước 3: Cập nhật vùng `<nav aria-label="Điều hướng chính">`
Thay thế đoạn JSX lặp `navigation.map(...)` cũ bằng:

```tsx
<nav aria-label="Điều hướng chính" className="sidebar__nav">
  {/* Mục độc lập trên cùng: Tổng quan */}
  <button
    type="button"
    className={page === 'dashboard' ? 'nav-item nav-item--active' : 'nav-item'}
    aria-current={page === 'dashboard' ? 'page' : undefined}
    onClick={() => go('dashboard')}
  >
    <Icon name="dashboard" size={18} />
    <span>{pageTitle['dashboard']}</span>
  </button>

  <div className="sidebar__divider" />

  {/* Các nhóm Accordion */}
  {navGroups.map((group) => {
    const isExpanded = expandedGroupId === group.id
    const hasActiveChild = group.items.some(item => item.page === page)

    return (
      <div key={group.id} className="nav-group-wrapper">
        <button
          type="button"
          className={[
            'nav-group-trigger',
            isExpanded ? 'nav-group-trigger--open' : '',
            hasActiveChild && !isExpanded ? 'nav-group-trigger--child-active' : '',
          ].filter(Boolean).join(' ')}
          onClick={() => toggleGroup(group.id)}
          aria-expanded={isExpanded}
        >
          <span className="nav-group-trigger__left">
            <Icon name={group.icon} size={18} />
            <span>{group.label}</span>
          </span>
          <span className={`nav-group-chevron ${isExpanded ? 'nav-group-chevron--open' : ''}`}>
            <Icon name="chevron" size={14} />
          </span>
        </button>

        {isExpanded && (
          <div className="nav-group-subitems" role="region">
            {group.items.map((item) => (
              <button
                key={item.page}
                type="button"
                className={page === item.page ? 'nav-item nav-subitem nav-item--active' : 'nav-item nav-subitem'}
                aria-current={page === item.page ? 'page' : undefined}
                onClick={() => go(item.page)}
              >
                <Icon name={item.icon} size={16} />
                <span>{pageTitle[item.page]}</span>
              </button>
            ))}
          </div>
        )}
      </div>
    )
  })}
</nav>
```

