```css
/* Phân cách giữa mục Tổng quan và các nhóm bên dưới */
.sidebar__divider {
  height: 1px;
  margin: 0.5rem 0.5rem 0.65rem;
  background: var(--color-border-dark, rgba(255, 255, 255, 0.08));
}

/* Khối bao từng nhóm Accordion */
.nav-group-wrapper {
  margin-bottom: 2px;
}

/* Nút bấm tiêu đề nhóm cha */
.nav-group-trigger {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  min-height: 40px;
  padding: 0.55rem 0.8rem;
  border: 0;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--color-amber-tint);
  font-size: var(--text-sm);
  font-weight: 600;
  text-align: left;
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease;
}

.nav-group-trigger:hover {
  background: rgba(255, 255, 255, 0.06);
  color: var(--color-white);
}

.nav-group-trigger--open {
  color: var(--color-white);
}

/* Nhóm cha đóng nhưng có trang con đang active */
.nav-group-trigger--child-active {
  color: var(--color-amber);
  background: rgba(217, 119, 6, 0.12);
}

.nav-group-trigger__left {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  min-width: 0;
}

.nav-group-trigger__left span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* Mũi tên đóng/mở */
.nav-group-chevron {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--color-subtle-dark);
  transition: transform 0.2s cubic-bezier(0.4, 0, 0.2, 1), color 0.15s ease;
}

.nav-group-trigger:hover .nav-group-chevron,
.nav-group-trigger--open .nav-group-chevron {
  color: var(--color-white);
}

.nav-group-chevron--open {
  transform: rotate(90deg);
}

/* Vùng chứa danh mục con */
.nav-group-subitems {
  margin-left: 1.15rem;
  padding-left: 0.65rem;
  margin-top: 2px;
  margin-bottom: 4px;
  border-left: 1.5px solid rgba(255, 255, 255, 0.12);
  display: flex;
  flex-direction: column;
  gap: 2px;
  animation: navSubitemsFadeIn 0.18s ease;
}

@keyframes navSubitemsFadeIn {
  from {
    opacity: 0;
    transform: translateY(-4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Mục con */
.nav-subitem {
  min-height: 36px;
  padding: 0.45rem 0.65rem;
  font-size: 0.83rem;
  border-radius: var(--radius-sm);
  color: rgba(255, 255, 255, 0.75);
}

.nav-subitem:hover {
  background: rgba(255, 255, 255, 0.05);
  color: var(--color-white);
}

.nav-subitem.nav-item--active {
  color: var(--color-white);
  background: var(--color-espresso-soft);
  font-weight: 700;
  box-shadow: inset 3px 0 0 var(--color-amber);
}
```

