@Composable
fun ReceiptScreen(
    receiptId: String,
    onNewOrder: () -> Unit,
    onBack: () -> Unit
) {
    val context = LocalContext.current
    val flow = remember(receiptId) {
        AppDatabase.getDatabase(context).salesDao().observeSale(receiptId)
    }
    val sale by flow.collectAsState(initial = null)
    var exportMessage by remember { mutableStateOf<String?>(null) }
    val currency = remember { NumberFormat.getCurrencyInstance(Locale.forLanguageTag("vi-VN")) }

    Column(
        modifier = Modifier.fillMaxSize().background(CoffeeCream).padding(32.dp),
        verticalArrangement = Arrangement.spacedBy(14.dp)
    ) {
        val current = sale
        if (current == null) {
            Text("Không tìm thấy hóa đơn.", color = Color(0xFFB91C1C))
            Button(onClick = onBack) { Text("Quay lại") }
            return@Column
        }

        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.SpaceBetween,
            verticalAlignment = Alignment.CenterVertically
        ) {
            Column {
                Text("HÓA ĐƠN ${current.saleNumber}", fontSize = 22.sp, fontWeight = FontWeight.Bold, color = CoffeeDarkRoast)
                Text("${current.storeName} · ${SimpleDateFormat("HH:mm dd/MM/yyyy", Locale.forLanguageTag("vi-VN")).format(Date(current.completedAt))}")
            }
            Row(horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                Button(onClick = onBack) { Text("Quay lại") }
                Button(
                    onClick = {
                        exportMessage = runCatching { ReceiptPdfExporter.export(context, current) }
                            .fold(
                                onSuccess = { "Đã xuất PDF: $it" },
                                onFailure = { it.message ?: "Xuất PDF thất bại." }
                            )
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = CoffeeAmber)
                ) { Text("XUẤT PDF", color = Color.White) }
            }
        }

        Card(
            colors = CardDefaults.cardColors(containerColor = Color.White),
            modifier = Modifier.fillMaxWidth().weight(1f)
        ) {
            LazyColumn(modifier = Modifier.fillMaxSize().padding(20.dp)) {
                items(OrderJsonSerializer.deserializeOrderItems(current.itemsJson), key = { it.lineId }) { item ->
                    Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                        Column(modifier = Modifier.weight(1f)) {
                            Text("${item.quantity} × ${item.product.name}", fontWeight = FontWeight.SemiBold)
                            Text(item.getCustomizationSummary(), fontSize = 12.sp, color = Color.Gray)
                        }
                        Text(currency.format(item.totalLinePrice), fontWeight = FontWeight.SemiBold)
                    }
                }
            }
        }

        Text("Tạm tính: ${currency.format(current.subtotalVnd)}")
        Text("VAT: ${currency.format(current.taxVnd)}")
        Text("Tổng thanh toán: ${currency.format(current.totalVnd)}", fontSize = 20.sp, fontWeight = FontWeight.Bold)
        Text("Khách đưa: ${currency.format(current.cashReceivedVnd)} · Tiền thừa: ${currency.format(current.changeVnd)}")
        exportMessage?.let { Text(it, color = Color(0xFF047857), fontSize = 12.sp) }
        Button(
            onClick = onNewOrder,
            colors = ButtonDefaults.buttonColors(containerColor = CoffeeAmber)
        ) { Text("ĐƠN HÀNG MỚI", color = Color.White, fontWeight = FontWeight.Bold) }
    }
}
"}}

