        when {
            balances == null -> Text("Đang đọc kho local…", color = TextSecondary)
            visible.isEmpty() -> Text("Chưa có nguyên liệu phù hợp. Kiểm tra từ khóa hoặc mở màn hình đồng bộ.", color = TextSecondary)
