function Register({
  role,
  store,
  realStores,
}: {
  role: Role
  store: string
  realStores: StoreResponse[]
}) {
  const [sessions, setSessions] = useState<RegisterSessionSummaryItem[]>([])
  const [loading, setLoading] = useState(false)
  const [statusFilter, setStatusFilter] = useState('Tất cả')

  const owner = role === 'OWNER'
  const chain = owner && store === 'Toàn chuỗi'
  const selectedStoreObj = realStores.find((s) => s.name === store)
  const storeIdParam = chain ? undefined : selectedStoreObj?.id

  useEffect(() => {
    let active = true
    setLoading(true)

    const statusParam =
      statusFilter === 'Đang mở' ? 'OPEN' : statusFilter === 'Đã đóng' ? 'CLOSED' : undefined

    registerSessionsApi
      .list({
        storeId: storeIdParam,
        status: statusParam,
        pageSize: 50,
      })
      .then((res) => {
        if (active) setSessions(res.items)
      })
      .catch((err) => {
        console.error('Lỗi tải danh sách ca két:', err)
        if (active) setSessions([])
      })
      .finally(() => {
        if (active) setLoading(false)
      })

    return () => {
      active = false
    }
  }, [storeIdParam, statusFilter])

  const openCount = sessions.filter((s) => s.status === 'OPEN').length
  const totalVarianceCount = sessions.filter(
    (s) => s.varianceVnd !== null && Number(s.varianceVnd) !== 0,
  ).length
  const totalCashRecorded = sessions.reduce((acc, s) => {
    return acc + Number(s.actualCashVnd || s.openingCashVnd || 0)
  }, 0)

  return (
    <>
      <Head
        title="Phiên tiền mặt & bàn giao"
        subtitle="Theo dõi quỹ mở, số tiền kết ca và chênh lệch két đối soát theo thời gian thực."
      />
      <div className="stats stats--three">
        <Stat
          title="Phiên đang mở"
          value={String(openCount).padStart(2, '0')}
          detail="Tại quầy thu ngân"
          icon="wallet"
          tone="amber"
        />
        <Stat
          title="Tiền mặt ghi nhận"
          value={formatMoney(totalCashRecorded)}
          detail="Tổng tiền các ca"
          icon="trend"
        />
        <Stat
          title="Chênh lệch cần xem"
          value={String(totalVarianceCount).padStart(2, '0')}
          detail="Phiên có lệch quỹ"
          icon="alert"
          tone={totalVarianceCount > 0 ? 'red' : 'green'}
        />
      </div>

      <section className="panel table-panel">
        <div className="table-toolbar">
          <SectionHead
            title="Lịch sử phiên quỹ"
            subtitle="Dữ liệu đối soát theo từng ca làm việc"
          />
          <div className="toolbar-actions">
            <label className="filter-select">
              <span className="sr-only">Lọc trạng thái</span>
              <select
                value={statusFilter}
                onChange={(event) => setStatusFilter(event.target.value)}
              >
                <option>Tất cả</option>
                <option>Đang mở</option>
                <option>Đã đóng</option>
              </select>
            </label>
            <span className="result-count">{sessions.length} phiên</span>
          </div>
        </div>
        <div className="table-scroll">
          <table>
            <thead>
              <tr>
                <th>Phiên</th>
                <th>Chi nhánh</th>
                <th>Người mở</th>
                <th>Thời gian</th>
                <th>Tiền đầu ca</th>
                <th>Chênh lệch</th>
                <th>Trạng thái</th>
              </tr>
            </thead>
            <tbody>
  openingCashVnd: string
  expectedCashVnd: string | null
  actualCashVnd: string | null
  varianceVnd: string | null
  status: string
  openedAt: string
  closedAt: string | null
}

export interface PaginatedRegisterSessionsResponse {
  items: RegisterSessionSummaryItem[]
  total: number
  page: number
  pageSize: number
  totalPages: number
}

export const registerSessionsApi = {
  list: (params?: {
    storeId?: string
    status?: string
    page?: number
    pageSize?: number
  }) => {
    const query = new URLSearchParams()
    if (params?.storeId) query.set('storeId', params.storeId)
    if (params?.status) query.set('status', params.status)
    if (params?.page) query.set('page', params.page.toString())
    if (params?.pageSize) query.set('pageSize', params.pageSize.toString())
    const qs = query.toString() ? `?${query.toString()}` : ''
    return request<PaginatedRegisterSessionsResponse>('GET', `/register-sessions${qs}`)
  },
  current: () => request<RegisterSessionSummaryItem | null>('GET', '/register-sessions/current'),
}

